#!/usr/bin/env python3
"""Generate BIEK Computer Science 12th Class Past Paper Analysis Report (2015-2025)."""

import csv
import re
from collections import Counter, defaultdict
from datetime import datetime

# ── Read data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# ── Basic aggregation ─────────────────────────────────────────────────────
year_type_counts = defaultdict(lambda: Counter())
for r in rows:
    year_type_counts[int(r["year"])][r["type"]] += 1

years_sorted = sorted(year_type_counts.keys())
all_years = list(range(2015, 2026))  # 2015-2025 inclusive
missing_years = [y for y in all_years if y not in years_sorted]

type_order = ["MCQs", "Short", "Long"]

# Per-year totals
yearly_totals = {}
for y in all_years:
    if y in year_type_counts:
        yearly_totals[y] = sum(year_type_counts[y].values())
    else:
        yearly_totals[y] = 0

# Overall type totals
overall_type = Counter()
for r in rows:
    overall_type[r["type"]] += 1

total_questions = len(rows)

# ── KPI: Average questions per type ───────────────────────────────────────
n_data_years = len(years_sorted)
avg_per_type = {}
for t in type_order:
    vals = [year_type_counts[y][t] for y in years_sorted]
    avg_per_type[t] = sum(vals) / len(vals) if vals else 0

# ── KPI: Year-over-Year change ────────────────────────────────────────────
yoy_changes = {}
prev = None
for y in all_years:
    curr = yearly_totals[y]
    if prev is not None and prev > 0 and curr > 0:
        yoy_changes[y] = {"abs": curr - prev, "pct": ((curr - prev) / prev) * 100}
    elif prev is not None and curr == 0:
        yoy_changes[y] = {"abs": None, "pct": None}  # missing year
    else:
        yoy_changes[y] = {"abs": None, "pct": None}
    if curr > 0:
        prev = curr

# ── Question type ratio per year ──────────────────────────────────────────
type_ratios = {}
for y in years_sorted:
    total = sum(year_type_counts[y].values())
    type_ratios[y] = {t: (year_type_counts[y][t] / total * 100) if total else 0 for t in type_order}

# ── Topic / Keyword analysis ──────────────────────────────────────────────
topic_keywords = {
    "C Data Types": [r"\bdata type\b", r"\bint\b", r"\bfloat\b", r"\bchar\b", r"\bdouble\b", r"\bvoid\b", r"\bsizeof\b", r"\bsize of\b", r"\bbytes\b", r"\brange of\b"],
    "Variables & Constants": [r"\bvariable\b", r"\bconstant\b", r"\bidentifier\b", r"\breserved word\b", r"\blocal variable\b", r"\bglobal variable\b", r"\bexternal variable\b", r"\bscope\b"],
    "Operators": [r"\boperator\b", r"\barithmetic operator\b", r"\brelational operator\b", r"\blogical operator\b", r"\bassignment operator\b", r"\bbitor operator\b", r"\bternary operator\b", r"\bincrement\b", r"\bdecrement\b", r"\bprecedence\b", r"\bunary operator\b", r"\bmodulus\b"],
    "Control Structures": [r"\bcontrol structure\b", r"\bif-?else\b", r"\bnested if\b", r"\bswitch\b", r"\belse-?if\b", r"\bdecision making\b", r"\bconditional\b"],
    "Loops": [r"\bloop\b", r"\bfor loop\b", r"\bwhile loop\b", r"\bdo-?while\b", r"\bnested loop\b", r"\biteration\b", r"\bcontinue\b", r"\bbreak\b"],
    "Functions": [r"\bfunction\b", r"\brecursion\b", r"\brecursive\b", r"\bprototype\b", r"\breturn\b", r"\bcall by value\b", r"\bcall by reference\b", r"\bparameter\b", r"\bargument\b", r"\bstorage class\b"],
    "Format Specifiers & I/O": [r"\bformat specifier\b", r"\bprintf\b", r"\bscanf\b", r"\bgetch\b", r"\bgets\b", r"\bputchar\b", r"\bescape sequence\b", r"\binput\b", r"\boutput\b", r"\bI/O\b", r"\bformatted\b", r"\bunformatted\b"],
    "Preprocessor & Comments": [r"\bpreprocessor\b", r"\b#include\b", r"\b#define\b", r"\bcomment\b", r"\bheader file\b"],
    "Arrays & Pointers": [r"\barray\b", r"\bpointer\b", r"\bstring\b", r"\bstrlen\b"],
    "Structures & Unions": [r"\bstructure\b", r"\bunion\b", r"\btype cast\b"],
    "File Handling": [r"\bfile\b", r"\bfopen\b", r"\bfclose\b", r"\bdata file\b", r"\bfile handling\b", r"\bfile opening mode\b"],
    "Errors & Debugging": [r"\berror\b", r"\bdebug\b", r"\bsyntax error\b", r"\blogical error\b", r"\bruntime error\b", r"\bcompiler\b", r"\binterpreter\b"],
    "DBMS Basics": [r"\bdbms\b", r"\brdbms\b", r"\bdatabase\b", r"\brelational database\b", r"\bnormali[sz]ation\b", r"\bdata redundancy\b", r"\bdata dictionary\b", r"\bschema\b", r"\bACID\b"],
    "Database Models": [r"\bmodel\b", r"\bhierarchical\b", r"\bnetwork model\b", r"\brelational model\b", r"\bobject-?oriented\b", r"\ber diagram\b", r"\bER diagram\b"],
    "Keys & Integrity": [r"\bprimary key\b", r"\bforeign key\b", r"\bcandidate key\b", r"\bcomposite key\b", r"\bsuper key\b", r"\balternate key\b", r"\bintegrity\b", r"\breferential\b", r"\bentity integrity\b"],
    "SQL": [r"\bsql\b", r"\bdml\b", r"\bddl\b", r"\bdcl\b", r"\btcl\b", r"\bquery\b"],
    "MS Access": [r"\bms-?access\b", r"\baccess\b", r"\btable\b", r"\bform\b", r"\breport\b", r"\bmacro\b", r"\bmodule\b", r"\bobject\b"],
    "Relationships": [r"\brelationship\b", r"\bone-?to-?one\b", r"\bone-?to-?many\b", r"\bmany-?to-?many\b", r"\bentity\b", r"\battribute\b", r"\btuple\b", r"\brecord\b", r"\bfield\b", r"\bview\b", r"\bindex\b"],
    "C Program Writing": [r"\bwrite a program\b", r"\bwrite the output\b", r"\bprogram to\b", r"\bconvert\b", r"\bcalculate\b", r"\bfind the\b", r"\bprint\b", r"\bcheck if\b"],
    "Mathematical Expressions": [r"\balgebraic\b", r"\bmathematical expression\b", r"\bequivalent\b", r"\bsqrt\b", r"\bpow\b", r"\babs\b"],
}

# Count topic occurrences per year and overall
topic_counts_overall = Counter()
topic_counts_by_year = defaultdict(lambda: Counter())
topic_counts_by_type = defaultdict(lambda: Counter())

for r in rows:
    q = r["question"].lower()
    year = int(r["year"])
    qtype = r["type"]
    matched = set()
    for topic, patterns in topic_keywords.items():
        for pat in patterns:
            if re.search(pat, q):
                matched.add(topic)
                break
    for t in matched:
        topic_counts_overall[t] += 1
        topic_counts_by_year[year][t] += 1
        topic_counts_by_type[qtype][t] += 1

# Top topics overall
top_topics = topic_counts_overall.most_common(20)

# ── Topic trend by year (for top topics) ──────────────────────────────────
top_topic_names = [t[0] for t in top_topics[:10]]

# ── MCQ option analysis (topic from options) ──────────────────────────────
mcq_topic_keywords = {
    "Data Types": [r"\bint\b", r"\bfloat\b", r"\bchar\b", r"\bdouble\b", r"\bbytes\b", r"\bdata type\b", r"\bsizeof\b"],
    "Operators": [r"\boperator\b", r"\bmodulus\b", r"\bincrement\b", r"\bdecrement\b", r"\bbitwise\b", r"\bternary\b"],
    "Loops & Control": [r"\bloop\b", r"\bfor\b", r"\bwhile\b", r"\bdo-while\b", r"\bswitch\b", r"\bbreak\b", r"\bcontinue\b", r"\bnested\b", r"\bgoto\b"],
    "Functions": [r"\bfunction\b", r"\brecursive\b", r"\bprototype\b", r"\breturn\b"],
    "I/O & Format": [r"\bprintf\b", r"\bscanf\b", r"\bformat specifier\b", r"\bescape sequence\b", r"\bgetch\b", r"\bgets\b"],
    "DBMS & RDBMS": [r"\bdbms\b", r"\brdbms\b", r"\bdatabase\b", r"\brecord\b", r"\btuple\b", r"\bfield\b", r"\battribute\b"],
    "Keys": [r"\bprimary key\b", r"\bforeign key\b", r"\bcandidate key\b", r"\bcomposite key\b", r"\bsuper key\b"],
    "MS Access": [r"\bms-?access\b", r"\btable\b", r"\bquery\b", r"\bform\b", r"\breport\b", r"\bmacro\b", r"\bmodule\b", r"\bobject\b"],
    "Database Models": [r"\bhierarchical\b", r"\bnetwork\b", r"\brelational\b", r"\bobject-?oriented\b"],
    "C Fundamentals": [r"\bcomment\b", r"\bpreprocessor\b", r"\b#include\b", r"\b#define\b", r"\bidentifier\b", r"\breserved\b", r"\bcompiler\b", r"\bsource code\b", r"\bflowchart\b"],
    "SQL": [r"\bsql\b", r"\bdml\b", r"\bddl\b", r"\bdcl\b", r"\btcl\b"],
    "File Handling": [r"\bfile\b", r"\bfclose\b", r"\bfopen\b"],
}

mcq_topic_by_year = defaultdict(lambda: Counter())
for r in rows:
    if r["type"] == "MCQs":
        q = r["question"].lower()
        year = int(r["year"])
        matched = set()
        for topic, patterns in mcq_topic_keywords.items():
            for pat in patterns:
                if re.search(pat, q):
                    matched.add(topic)
                    break
        for t in matched:
            mcq_topic_by_year[year][t] += 1

# ── Build HTML ─────────────────────────────────────────────────────────────

def js_array(arr):
    """Convert Python list to JS array literal."""
    return str(arr)

def js_array_of_strings(arr):
    """Convert Python list of strings to JS array of string literals."""
    return "[" + ", ".join(f'"{v}"' for v in arr) + "]"

# Year-by-year data for charts
years_labels = [str(y) for y in all_years]
mcqs_data = [year_type_counts[y]["MCQs"] if y in year_type_counts else 0 for y in all_years]
short_data = [year_type_counts[y]["Short"] if y in year_type_counts else 0 for y in all_years]
long_data = [year_type_counts[y]["Long"] if y in year_type_counts else 0 for y in all_years]
total_data = [yearly_totals[y] for y in all_years]

# Percentage data for stacked chart
mcqs_pct = []
short_pct = []
long_pct = []
for y in all_years:
    t = yearly_totals[y]
    if t > 0:
        mcqs_pct.append(round(year_type_counts[y]["MCQs"] / t * 100, 1))
        short_pct.append(round(year_type_counts[y]["Short"] / t * 100, 1))
        long_pct.append(round(year_type_counts[y]["Long"] / t * 100, 1))
    else:
        mcqs_pct.append(0)
        short_pct.append(0)
        long_pct.append(0)

# Topic trend data (for line chart)
topic_trend_datasets = []
colors = [
    ("#3366CC", "rgba(51,102,204,0.15)"),
    ("#DC3912", "rgba(220,57,18,0.15)"),
    ("#FF9900", "rgba(255,153,0,0.15)"),
    ("#109618", "rgba(16,150,24,0.15)"),
    ("#990099", "rgba(153,0,153,0.15)"),
    ("#0099C6", "rgba(0,153,198,0.15)"),
    ("#DD4477", "rgba(221,68,119,0.15)"),
    ("#66AA00", "rgba(102,170,0,0.15)"),
    ("#B82E2E", "rgba(184,46,46,0.15)"),
    ("#316395", "rgba(49,99,149,0.15)"),
]

for idx, topic in enumerate(top_topic_names):
    data = [topic_counts_by_year[y][topic] if y in topic_counts_by_year else 0 for y in all_years]
    color, bg = colors[idx % len(colors)]
    topic_trend_datasets.append({
        "label": topic,
        "data": data,
        "borderColor": color,
        "backgroundColor": bg,
        "fill": False,
        "tension": 0.3,
        "pointRadius": 4,
        "borderWidth": 2,
    })

# Build topic trend JS
topic_trend_ds_js = "[\n"
for ds in topic_trend_datasets:
    topic_trend_ds_js += f'    {{label: "{ds["label"]}", data: {js_array(ds["data"])}, borderColor: "{ds["borderColor"]}", backgroundColor: "{ds["backgroundColor"]}", fill: false, tension: 0.3, pointRadius: 4, borderWidth: 2}},\n'
topic_trend_ds_js += "]"

# Build overall topic bar chart data
topic_names_bar = [t[0] for t in top_topics]
topic_counts_bar = [t[1] for t in top_topics]

# Topic by type stacked bar
topic_by_type_labels = [t[0] for t in top_topics[:12]]
topic_by_type_mcqs = [topic_counts_by_type["MCQs"][t] for t in topic_by_type_labels]
topic_by_type_short = [topic_counts_by_type["Short"][t] for t in topic_by_type_labels]
topic_by_type_long = [topic_counts_by_type["Long"][t] for t in topic_by_type_labels]

# ── YoY table rows ────────────────────────────────────────────────────────
yoy_table_rows = ""
for y in all_years:
    mcq = year_type_counts[y]["MCQs"] if y in year_type_counts else "-"
    short = year_type_counts[y]["Short"] if y in year_type_counts else "-"
    long_q = year_type_counts[y]["Long"] if y in year_type_counts else "-"
    total = yearly_totals[y]
    total_str = str(total) if total > 0 else '<span class="missing">No Data</span>'

    if y in yoy_changes and yoy_changes[y]["abs"] is not None:
        abs_c = yoy_changes[y]["abs"]
        pct_c = yoy_changes[y]["pct"]
        arrow = "&#9650;" if abs_c > 0 else "&#9660;" if abs_c < 0 else "&#9654;"
        cls = "positive" if abs_c > 0 else "negative" if abs_c < 0 else "neutral"
        yoy_str = f'<span class="{cls}">{arrow} {abs_c:+d} ({pct_c:+.1f}%)</span>'
    elif y == 2015:
        yoy_str = '<span class="neutral">Baseline</span>'
    elif y == 2020:
        yoy_str = '<span class="missing">No data</span>'
    elif y == 2021:
        yoy_str = '<span class="missing">Gap from 2019</span>'
    else:
        yoy_str = '<span class="neutral">-</span>'

    # Type ratio
    if y in type_ratios:
        ratio_str = f'{type_ratios[y]["MCQs"]:.0f}% / {type_ratios[y]["Short"]:.0f}% / {type_ratios[y]["Long"]:.0f}%'
    else:
        ratio_str = '-'

    yoy_table_rows += f"""<tr>
        <td>{y}</td>
        <td>{mcq}</td>
        <td>{short}</td>
        <td>{long_q}</td>
        <td>{total_str}</td>
        <td>{ratio_str}</td>
        <td>{yoy_str}</td>
    </tr>"""

# ── Topic frequency table ─────────────────────────────────────────────────
topic_table_rows = ""
for rank, (topic, count) in enumerate(top_topics, 1):
    pct = count / total_questions * 100
    bar_width = min(pct * 3, 100)
    topic_table_rows += f"""<tr>
        <td>{rank}</td>
        <td>{topic}</td>
        <td>{count}</td>
        <td>{pct:.1f}%</td>
        <td><div class="bar-bg"><div class="bar-fill" style="width:{bar_width}%"></div></div></td>
    </tr>"""

# ── Topic by type table ───────────────────────────────────────────────────
topic_type_table_rows = ""
for topic in topic_by_type_labels:
    mcq_c = topic_counts_by_type["MCQs"][topic]
    short_c = topic_counts_by_type["Short"][topic]
    long_c = topic_counts_by_type["Long"][topic]
    total_c = mcq_c + short_c + long_c
    topic_type_table_rows += f"""<tr>
        <td>{topic}</td>
        <td>{mcq_c}</td>
        <td>{short_c}</td>
        <td>{long_c}</td>
        <td>{total_c}</td>
    </tr>"""

# ── MCQ topic distribution table ──────────────────────────────────────────
mcq_topic_totals = Counter()
for y in years_sorted:
    for topic, cnt in mcq_topic_by_year[y].items():
        mcq_topic_totals[topic] += cnt
mcq_top_topics = mcq_topic_totals.most_common(8)

mcq_topic_table_rows = ""
for topic, total in mcq_top_topics:
    yearly_detail = []
    for y in all_years:
        if y in mcq_topic_by_year:
            c = mcq_topic_by_year[y][topic]
            yearly_detail.append(str(c) if c > 0 else "0")
        else:
            yearly_detail.append("-")
    mcq_topic_table_rows += f"""<tr>
        <td>{topic}</td>
        <td>{total}</td>
        <td>{", ".join(yearly_detail)}</td>
    </tr>"""

# ── Anomalies and insights ────────────────────────────────────────────────
# Calculate which years deviate most from average
anomalies = []
for y in years_sorted:
    for t in type_order:
        val = year_type_counts[y][t]
        avg = avg_per_type[t]
        if avg > 0:
            dev_pct = (val - avg) / avg * 100
            if abs(dev_pct) > 20:
                direction = "above" if dev_pct > 0 else "below"
                anomalies.append((y, t, val, avg, dev_pct, direction))

anomalies.sort(key=lambda x: abs(x[4]), reverse=True)

anomaly_insights = ""
for y, t, val, avg, dev_pct, direction in anomalies[:8]:
    anomaly_insights += f"""<li><strong>{y} {t}</strong>: {val} questions — {abs(dev_pct):.0f}% {direction} the 10-year average of {avg:.1f}</li>"""

# ── Phase classification ──────────────────────────────────────────────────
phase_info = """
<div class="phase-card">
    <h4>Phase 1: Early Period (2015–2016)</h4>
    <p>27 questions per year: 15 MCQs, 9 Short, 3 Long. The exam featured the fewest short questions, making it the most compact paper structure in the dataset.</p>
</div>
<div class="phase-card">
    <h4>Phase 2: Expansion Period (2017–2019)</h4>
