# Topic by type stacked bar
topic_by_type_labels = [t[0] for t in top_topics[:12]]
topic_by_type_mcqs = [topic_counts_by_type["MCQs"][t] for t in topic_by_type_labels]
topic_by_type_short = [topic_counts_by_type["Short"][t] for t in topic_by_type_labels]
topic_by_type_long = [topic_counts_by_type["Long"][t] for t in topic_by_type_labels]

# ── YoY table rows ────────────────────────────────────────────────────────
yoy_table_rows = ""
for y in all_years:
    mcq = year_type_counts[y]["MCQs"] if y in year_type_counts else "-"
    short = year_type_counts[y]["Short"] if y in year_type_counts else "-"
    long_q = year_type_counts[y]["Long"] if y in year_type_counts else "-"
    total = yearly_totals[y]
    total_str = str(total) if total > 0 else '<span class="missing">No Data</span>'

    if y in yoy_changes and yoy_changes[y]["abs"] is not None:
        abs_c = yoy_changes[y]["abs"]
        pct_c = yoy_changes[y]["pct"]
        arrow = "&#9650;" if abs_c > 0 else "&#9660;" if abs_c < 0 else "&#9654;"
        cls = "positive" if abs_c > 0 else "negative" if abs_c < 0 else "neutral"
        yoy_str = f'<span class="{cls}">{arrow} {abs_c:+d} ({pct_c:+.1f}%)</span>'
    elif y == 2015:
        yoy_str = '<span class="neutral">Baseline</span>'
    elif y == 2020:
        yoy_str = '<span class="missing">No data</span>'
    elif y == 2021:
        yoy_str = '<span class="missing">Gap from 2019</span>'
    else:
        yoy_str = '<span class="neutral">-</span>'

    # Type ratio
    if y in type_ratios:
        ratio_str = f'{type_ratios[y]["MCQs"]:.0f}% / {type_ratios[y]["Short"]:.0f}% / {type_ratios[y]["Long"]:.0f}%'
    else:
        ratio_str = '-'

    yoy_table_rows += f"""<tr>
        <td>{y}</td>
        <td>{mcq}</td>
        <td>{short}</td>
        <td>{long_q}</td>
        <td>{total_str}</td>
        <td>{ratio_str}</td>
        <td>{yoy_str}</td>
    </tr>"""

# ── Topic frequency table ─────────────────────────────────────────────────
topic_table_rows = ""
for rank, (topic, count) in enumerate(top_topics, 1):
    pct = count / total_questions * 100
    bar_width = min(pct * 3, 100)
    topic_table_rows += f"""<tr>
        <td>{rank}</td>
        <td>{topic}</td>
        <td>{count}</td>
        <td>{pct:.1f}%</td>
        <td><div class="bar-bg"><div class="bar-fill" style="width:{bar_width}%"></div></div></td>
    </tr>"""

# ── Topic by type table ───────────────────────────────────────────────────
topic_type_table_rows = ""
for topic in topic_by_type_labels:
    mcq_c = topic_counts_by_type["MCQs"][topic]
    short_c = topic_counts_by_type["Short"][topic]
    long_c = topic_counts_by_type["Long"][topic]
    total_c = mcq_c + short_c + long_c
    topic_type_table_rows += f"""<tr>
        <td>{topic}</td>
        <td>{mcq_c}</td>
        <td>{short_c}</td>
        <td>{long_c}</td>
        <td>{total_c}</td>
    </tr>"""

# ── MCQ topic distribution table ──────────────────────────────────────────
mcq_topic_totals = Counter()
for y in years_sorted:
    for topic, cnt in mcq_topic_by_year[y].items():
        mcq_topic_totals[topic] += cnt
mcq_top_topics = mcq_topic_totals.most_common(8)

mcq_topic_table_rows = ""
for topic, total in mcq_top_topics:
    yearly_detail = []
    for y in all_years:
        if y in mcq_topic_by_year:
            c = mcq_topic_by_year[y][topic]
            yearly_detail.append(str(c) if c > 0 else "0")
        else:
            yearly_detail.append("-")
    mcq_topic_table_rows += f"""<tr>
        <td>{topic}</td>
        <td>{total}</td>
        <td>{", ".join(yearly_detail)}</td>
    </tr>"""

# ── Anomalies and insights ────────────────────────────────────────────────
# Calculate which years deviate most from average
anomalies = []
for y in years_sorted:
    for t in type_order:
        val = year_type_counts[y][t]
        avg = avg_per_type[t]
        if avg > 0:
            dev_pct = (val - avg) / avg * 100
            if abs(dev_pct) > 20:
                direction = "above" if dev_pct > 0 else "below"
                anomalies.append((y, t, val, avg, dev_pct, direction))

anomalies.sort(key=lambda x: abs(x[4]), reverse=True)

anomaly_insights = ""
for y, t, val, avg, dev_pct, direction in anomalies[:8]:
    anomaly_insights += f"""<li><strong>{y} {t}</strong>: {val} questions — {abs(dev_pct):.0f}% {direction} the 10-year average of {avg:.1f}</li>"""

