# Find the most consistently tested topics
consistent_topics = []
for topic in top_topic_names[:8]:
    years_present = sum(1 for y in years_sorted if topic_counts_by_year[y][topic] > 0)
    consistent_topics.append((topic, years_present, years_present / n_data_years * 100))

# Topics that are increasing
increasing_topics = []
for topic in top_topic_names[:10]:
    early = sum(topic_counts_by_year[y][topic] for y in [2015, 2016, 2017] if y in topic_counts_by_year)
    late = sum(topic_counts_by_year[y][topic] for y in [2023, 2024, 2025] if y in topic_counts_by_year)
    if early > 0:
        change = (late - early) / early * 100
        increasing_topics.append((topic, early, late, change))

increasing_topics.sort(key=lambda x: x[3], reverse=True)

