#!/usr/bin/env python3
"""Generate BIEK Computer Science 12th Class Past Paper Analysis Report (2015-2025)."""

import csv
import re
from collections import Counter, defaultdict
from datetime import datetime

# ── Read data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# ── Basic aggregation ─────────────────────────────────────────────────────
year_type_counts = defaultdict(lambda: Counter())
for r in rows:
    year_type_counts[int(r["year"])][r["type"]] += 1

years_sorted = sorted(year_type_counts.keys())
all_years = list(range(2015, 2026))  # 2015-2025 inclusive
missing_years = [y for y in all_years if y not in years_sorted]

type_order = ["MCQs", "Short", "Long"]

# Per-year totals
yearly_totals = {}
for y in all_years:
    if y in year_type_counts:
        yearly_totals[y] = sum(year_type_counts[y].values())
    else:
        yearly_totals[y] = 0

# Overall type totals
overall_type = Counter()
for r in rows:
    overall_type[r["type"]] += 1

total_questions = len(rows)

# ── KPI: Average questions per type ───────────────────────────────────────
n_data_years = len(years_sorted)
avg_per_type = {}
for t in type_order:
    vals = [year_type_counts[y][t] for y in years_sorted]
    avg_per_type[t] = sum(vals) / len(vals) if vals else 0

# ── KPI: Year-over-Year change ────────────────────────────────────────────
yoy_changes = {}
prev = None
for y in all_years:
    curr = yearly_totals[y]
    if prev is not None and prev > 0 and curr > 0:
        yoy_changes[y] = {"abs": curr - prev, "pct": ((curr - prev) / prev) * 100}
    elif prev is not None and curr == 0:
        yoy_changes[y] = {"abs": None, "pct": None}  # missing year
    else:
        yoy_changes[y] = {"abs": None, "pct": None}
    if curr > 0:
        prev = curr

# ── Question type ratio per year ──────────────────────────────────────────
type_ratios = {}
for y in years_sorted:
    total = sum(year_type_counts[y].values())
    type_ratios[y] = {t: (year_type_counts[y][t] / total * 100) if total else 0 for t in type_order}

# ── Topic / Keyword analysis ──────────────────────────────────────────────
topic_keywords = {
    "C Data Types": [r"\bdata type\b", r"\bint\b", r"\bfloat\b", r"\bchar\b", r"\bdouble\b", r"\bvoid\b", r"\bsizeof\b", r"\bsize of\b", r"\bbytes\b", r"\brange of\b"],
    "Variables & Constants": [r"\bvariable\b", r"\bconstant\b", r"\bidentifier\b", r"\breserved word\b", r"\blocal variable\b", r"\bglobal variable\b", r"\bexternal variable\b", r"\bscope\b"],
    "Operators": [r"\boperator\b", r"\barithmetic operator\b", r"\brelational operator\b", r"\blogical operator\b", r"\bassignment operator\b", r"\bbitor operator\b", r"\bternary operator\b", r"\bincrement\b", r"\bdecrement\b", r"\bprecedence\b", r"\bunary operator\b", r"\bmodulus\b"],
    "Control Structures": [r"\bcontrol structure\b", r"\bif-?else\b", r"\bnested if\b", r"\bswitch\b", r"\belse-?if\b", r"\bdecision making\b", r"\bconditional\b"],
    "Loops": [r"\bloop\b", r"\bfor loop\b", r"\bwhile loop\b", r"\bdo-?while\b", r"\bnested loop\b", r"\biteration\b", r"\bcontinue\b", r"\bbreak\b"],
    "Functions": [r"\bfunction\b", r"\brecursion\b", r"\brecursive\b", r"\bprototype\b", r"\breturn\b", r"\bcall by value\b", r"\bcall by reference\b", r"\bparameter\b", r"\bargument\b", r"\bstorage class\b"],
    "Format Specifiers & I/O": [r"\bformat specifier\b", r"\bprintf\b", r"\bscanf\b", r"\bgetch\b", r"\bgets\b", r"\bputchar\b", r"\bescape sequence\b", r"\binput\b", r"\boutput\b", r"\bI/O\b", r"\bformatted\b", r"\bunformatted\b"],
    "Preprocessor & Comments": [r"\bpreprocessor\b", r"\b#include\b", r"\b#define\b", r"\bcomment\b", r"\bheader file\b"],
    "Arrays & Pointers": [r"\barray\b", r"\bpointer\b", r"\bstring\b", r"\bstrlen\b"],
    "Structures & Unions": [r"\bstructure\b", r"\bunion\b", r"\btype cast\b"],
    "File Handling": [r"\bfile\b", r"\bfopen\b", r"\bfclose\b", r"\bdata file\b", r"\bfile handling\b", r"\bfile opening mode\b"],
    "Errors & Debugging": [r"\berror\b", r"\bdebug\b", r"\bsyntax error\b", r"\blogical error\b", r"\bruntime error\b", r"\bcompiler\b", r"\binterpreter\b"],
    "DBMS Basics": [r"\bdbms\b", r"\brdbms\b", r"\bdatabase\b", r"\brelational database\b", r"\bnormali[sz]ation\b", r"\bdata redundancy\b", r"\bdata dictionary\b", r"\bschema\b", r"\bACID\b"],
    "Database Models": [r"\bmodel\b", r"\bhierarchical\b", r"\bnetwork model\b", r"\brelational model\b", r"\bobject-?oriented\b", r"\ber diagram\b", r"\bER diagram\b"],
    "Keys & Integrity": [r"\bprimary key\b", r"\bforeign key\b", r"\bcandidate key\b", r"\bcomposite key\b", r"\bsuper key\b", r"\balternate key\b", r"\bintegrity\b", r"\breferential\b", r"\bentity integrity\b"],
    "SQL": [r"\bsql\b", r"\bdml\b", r"\bddl\b", r"\bdcl\b", r"\btcl\b", r"\bquery\b"],
    "MS Access": [r"\bms-?access\b", r"\baccess\b", r"\btable\b", r"\bform\b", r"\breport\b", r"\bmacro\b", r"\bmodule\b", r"\bobject\b"],
    "Relationships": [r"\brelationship\b", r"\bone-?to-?one\b", r"\bone-?to-?many\b", r"\bmany-?to-?many\b", r"\bentity\b", r"\battribute\b", r"\btuple\b", r"\brecord\b", r"\bfield\b", r"\bview\b", r"\bindex\b"],
    "C Program Writing": [r"\bwrite a program\b", r"\bwrite the output\b", r"\bprogram to\b", r"\bconvert\b", r"\bcalculate\b", r"\bfind the\b", r"\bprint\b", r"\bcheck if\b"],
    "Mathematical Expressions": [r"\balgebraic\b", r"\bmathematical expression\b", r"\bequivalent\b", r"\bsqrt\b", r"\bpow\b", r"\babs\b"],
}

# Count topic occurrences per year and overall
topic_counts_overall = Counter()
topic_counts_by_year = defaultdict(lambda: Counter())
topic_counts_by_type = defaultdict(lambda: Counter())

for r in rows:
    q = r["question"].lower()
    year = int(r["year"])
    qtype = r["type"]
    matched = set()
    for topic, patterns in topic_keywords.items():
        for pat in patterns:
            if re.search(pat, q):
                matched.add(topic)
                break
    for t in matched:
        topic_counts_overall[t] += 1
        topic_counts_by_year[year][t] += 1
        topic_counts_by_type[qtype][t] += 1

# Top topics overall
top_topics = topic_counts_overall.most_common(20)

# ── Topic trend by year (for top topics) ──────────────────────────────────
top_topic_names = [t[0] for t in top_topics[:10]]

# ── MCQ option analysis (topic from options) ──────────────────────────────
mcq_topic_keywords = {
