#!/usr/bin/env python3
"""Generate BIEK Computer Science 12th Class Past Paper Analysis Report (2015-2025)."""

import csv
import re
from collections import Counter, defaultdict
from datetime import datetime

# ── Read data ──────────────────────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# ── Basic aggregation ─────────────────────────────────────────────────────
year_type_counts = defaultdict(lambda: Counter())
for r in rows:
    year_type_counts[int(r["year"])][r["type"]] += 1

years_sorted = sorted(year_type_counts.keys())
all_years = list(range(2015, 2026))  # 2015-2025 inclusive
missing_years = [y for y in all_years if y not in years_sorted]

type_order = ["MCQs", "Short", "Long"]

# Per-year totals
yearly_totals = {}
for y in all_years:
    if y in year_type_counts:
        yearly_totals[y] = sum(year_type_counts[y].values())
    else:
        yearly_totals[y] = 0

# Overall type totals
overall_type = Counter()
for r in rows:
    overall_type[r["type"]] += 1

total_questions = len(rows)

# ── KPI: Average questions per type ───────────────────────────────────────
n_data_years = len(years_sorted)
avg_per_type = {}
for t in type_order:
    vals = [year_type_counts[y][t] for y in years_sorted]
    avg_per_type[t] = sum(vals) / len(vals) if vals else 0

# ── KPI: Year-over-Year change ────────────────────────────────────────────
yoy_changes = {}
prev = None
for y in all_years:
    curr = yearly_totals[y]
    if prev is not None and prev > 0 and curr > 0:
        yoy_changes[y] = {"abs": curr - prev, "pct": ((curr - prev) / prev) * 100}
    elif prev is not None and curr == 0:
        yoy_changes[y] = {"abs": None, "pct": None}  # missing year
    else:
        yoy_changes[y] = {"abs": None, "pct": None}
    if curr > 0:
        prev = curr

# ── Question type ratio per year ──────────────────────────────────────────
type_ratios = {}
for y in years_sorted:
    total = sum(year_type_counts[y].values())
    type_ratios[y] = {t: (year_type_counts[y][t] / total * 100) if total else 0 for t in type_order}

