    "Operators": [r"\boperator\b", r"\bmodulus\b", r"\bincrement\b", r"\bdecrement\b", r"\bbitwise\b", r"\bternary\b"],
    "Loops & Control": [r"\bloop\b", r"\bfor\b", r"\bwhile\b", r"\bdo-while\b", r"\bswitch\b", r"\bbreak\b", r"\bcontinue\b", r"\bnested\b", r"\bgoto\b"],
    "Functions": [r"\bfunction\b", r"\brecursive\b", r"\bprototype\b", r"\breturn\b"],
    "I/O & Format": [r"\bprintf\b", r"\bscanf\b", r"\bformat specifier\b", r"\bescape sequence\b", r"\bgetch\b", r"\bgets\b"],
    "DBMS & RDBMS": [r"\bdbms\b", r"\brdbms\b", r"\bdatabase\b", r"\brecord\b", r"\btuple\b", r"\bfield\b", r"\battribute\b"],
    "Keys": [r"\bprimary key\b", r"\bforeign key\b", r"\bcandidate key\b", r"\bcomposite key\b", r"\bsuper key\b"],
    "MS Access": [r"\bms-?access\b", r"\btable\b", r"\bquery\b", r"\bform\b", r"\breport\b", r"\bmacro\b", r"\bmodule\b", r"\bobject\b"],
    "Database Models": [r"\bhierarchical\b", r"\bnetwork\b", r"\brelational\b", r"\bobject-?oriented\b"],
    "C Fundamentals": [r"\bcomment\b", r"\bpreprocessor\b", r"\b#include\b", r"\b#define\b", r"\bidentifier\b", r"\breserved\b", r"\bcompiler\b", r"\bsource code\b", r"\bflowchart\b"],
