# Year-by-year data for charts
years_labels = [str(y) for y in all_years]
mcqs_data = [year_type_counts[y]["MCQs"] if y in year_type_counts else 0 for y in all_years]
short_data = [year_type_counts[y]["Short"] if y in year_type_counts else 0 for y in all_years]
