topic_by_type_short = [topic_counts_by_type["Short"][t] for t in topic_by_type_labels]
topic_by_type_long = [topic_counts_by_type["Long"][t] for t in topic_by_type_labels]

# ── YoY table rows ────────────────────────────────────────────────────────
yoy_table_rows = ""
for y in all_years:
    mcq = year_type_counts[y]["MCQs"] if y in year_type_counts else "-"
