from html.parser import HTMLParser
class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','hr','img','input','meta','link','canvas','source'):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in ('br','hr','img','input','meta','link','canvas','source'):
            if self.stack and self.stack[-1] == tag:
                self.stack.pop()
            else:
                self.errors.append(f'Mismatched tag: </{tag}>, expected </{self.stack[-1] if self.stack else \"nothing\"}>')

c = Checker()
with open('/app/output/final_report.html') as f:
    c.feed(f.read())
if c.errors:
    for e in c.errors[:5]:
        print('ERROR:', e)
else:
    print('HTML structure looks valid')
print(f'Unclosed tags: {c.stack[-5:] if c.stack else \"none\"}')
"

